INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `status`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'Booking', 'How do I book a parking spot in advance?', 'Simply search your desired destination or parking facility, select your vehicle type, choose arrival date and duration, and confirm your booking with a secure payment. You will receive an instant digital pass with a QR code.', 'Active', 1, '2026-09-22 11:54:01', '2026-09-22 11:54:01'),
(2, 'Booking', 'Can I cancel or modify my reservation?', 'Yes, you can cancel or reschedule your reservation up to 1 hour before your scheduled arrival time directly from your dashboard or mobile app. Refunds are processed automatically to your original payment method.', 'Active', 2, '2026-09-22 11:54:01', '2026-09-22 11:54:01'),
(3, 'Access', 'How does the QR code entry work?', 'When you arrive at the parking facility barrier, hold your digital QR code (from your email or app) up to the optical scanner. The barrier will verify your booking and raise automatically within seconds.', 'Active', 3, '2026-09-22 11:54:01', '2026-09-22 11:54:01'),
(4, 'Payment', 'What payment methods are supported?', 'We accept all major credit and debit cards (Visa, MasterCard, American Express), digital wallets (Google Pay, Apple Pay), and net banking. All transactions are 256-bit SSL encrypted.', 'Active', 4, '2026-09-22 11:54:01', '2026-09-22 11:54:01'),
(5, 'Policy', 'What happens if I exceed my booked parking time?', 'If your stay exceeds your reserved period, overtime charges will be calculated at standard hourly facility rates and automatically charged to your linked payment method upon exit scan.', 'Active', 5, '2026-09-22 11:54:01', '2026-09-22 11:54:01');
INSERT INTO `how_it_works_cta` (`id`, `eyebrow`, `title`, `description`, `main_image`, `google_play_url`, `app_store_url`, `status`, `created_at`, `updated_at`) VALUES
(1, 'SMARTER PARKING', 'Your Next Parking Spot is Just a Few Taps Away!', 'Download the SmartParking app to easily search, reserve, and navigate to parking spaces anytime, anywhere. Experience seamless contactless parking today.', 'images/how-it-works/cta-phone.png', 'https://play.google.com', 'https://apps.apple.com', 'Active', '2026-09-22 11:54:01', '2026-09-22 11:54:01');
INSERT INTO `how_it_works_cta_features` (`id`, `icon`, `title`, `description`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES
(1, 'bi-geo-alt-fill', 'Find Nearby Parking', 'Instantly locate available parking spots around your current or target location.', 1, 'Active', '2026-09-22 11:54:01', '2026-09-22 11:54:01'),
(2, 'bi-clock-history', 'Real-Time Availability', 'Live slot tracking and instant occupancy updates powered by smart sensors.', 2, 'Active', '2026-09-22 11:54:01', '2026-09-22 11:54:01'),
(3, 'bi-shield-check', 'Secure Payments', 'Multiple contactless payment options with encrypted digital transactions.', 3, 'Active', '2026-09-22 11:54:01', '2026-09-22 11:54:01'),
(4, 'bi-lightning-charge-fill', 'Easy & Fast Booking', 'Reserve and confirm your ideal spot within seconds from your smartphone.', 4, 'Active', '2026-09-22 11:54:01', '2026-09-22 11:54:01');
INSERT INTO `how_it_works_page_settings` (`id`, `hero_eyebrow`, `hero_title`, `hero_highlight`, `hero_description`, `hero_image`, `section_title`, `section_description`, `faq_eyebrow`, `faq_title`, `faq_highlight`, `faq_description`, `seo_title`, `seo_description`, `seo_keywords`, `og_image`, `status`, `created_at`, `updated_at`) VALUES
(1, 'EASY 4-STEP PARKING', 'Parking Is Now', 'Effortless', 'Tested dynamic description update.', 'images/how-it-works/hero-facility.png', 'Simple Steps', 'Fast and easy process.', 'HELP & FAQ', 'Common', 'Inquiries', 'Find quick answers to common questions.', 'How SmartParking AI Works', 'Discover how easy parking is with SmartParking AI. 4 simple steps to reserve your spot.', NULL, NULL, 'Active', '2026-09-22 11:54:01', '2026-09-23 11:52:55');
INSERT INTO `how_it_works_steps` (`id`, `step_number`, `title`, `description`, `image`, `icon`, `button_text`, `button_url`, `status`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, '01', 'Find a Location', 'Search for parking spaces near your destination and compare prices and amenities.', 'images/how-it-works/step-01.png', 'bi-search', NULL, NULL, 'Active', 1, '2026-09-22 11:54:01', '2026-09-22 11:54:01'),
(2, '02', 'Book Your Slot', 'Choose your date, time and parking slot that best fits your schedule and vehicle.', 'images/how-it-works/step-02.png', 'bi-calendar3', NULL, NULL, 'Active', 2, '2026-09-22 11:54:01', '2026-09-22 11:54:01'),
(3, '03', 'Get Confirmation', 'Receive instant confirmation with a QR code and detailed navigation directions.', 'images/how-it-works/step-03.png', 'bi-qr-code-scan', NULL, NULL, 'Active', 3, '2026-09-22 11:54:01', '2026-09-22 11:54:01'),
(4, '04', 'Park & Enjoy', 'Scan, enter and park with ease. Enjoy a completely hassle-free parking experience.', 'images/how-it-works/step-04.png', 'bi-car-front-fill', NULL, NULL, 'Active', 4, '2026-09-22 11:54:01', '2026-09-22 11:54:01');
