(20, 'parking_rules_text', '1. Park strictly within designated bay lines.\n2. Present your digital QR code upon vehicle entry.\n3. Overstaying exceeding the 15-minute grace period incurs a 1.5x hourly rate penalty.\n4. EV Charging bays are reserved exclusively for electric vehicles while actively charging.', 'rules', '2026-09-21 13:59:34', '2026-09-21 13:59:34'),
(21, 'hero_title', 'Instant Smart Parking at Your Fingertips', 'homepage', '2026-09-21 13:59:34', '2026-09-21 13:59:34'),
(22, 'hero_description', 'Search facilities, inspect live visual slot grids in real time, reserve guaranteed parking bays, and breeze through barrier gates with automated verification.', 'homepage', '2026-09-21 13:59:34', '2026-09-21 13:59:34'),
(23, 'about_title', 'Why Drivers & Operators Love SMARTPARK AI', 'homepage', '2026-09-21 13:59:34', '2026-09-21 13:59:34'),
(24, 'about_description', 'SMARTPARK AI replaces circling crowded lots with seamless pre-booking, live availability boards, instant QR validation, automated overtime billing, and demand analytics.', 'homepage', '2026-09-21 13:59:34', '2026-09-21 13:59:34'),
(25, 'site_brand_first', 'Smart', 'general', '2026-09-22 10:32:52', '2026-09-23 12:31:50'),
(26, 'site_brand_second', 'Parking', 'general', '2026-09-22 10:32:52', '2026-09-23 12:31:50'),
(27, 'app_tagline', 'Park Smarter. Live Easier.', 'general', '2026-09-22 10:32:52', '2026-09-23 12:31:50'),
(28, 'hero_title_line1', 'Find &amp; Book', 'general', '2026-09-22 10:32:52', '2026-09-23 12:31:50'),
(29, 'hero_title_line2', 'Parking', 'general', '2026-09-22 10:32:52', '2026-09-23 12:31:50'),
(30, 'hero_title_highlight', 'Instantly', 'general', '2026-09-22 10:32:52', '2026-09-23 12:31:50'),
(31, 'hero_subtitle', 'Smart parking for a smarter tomorrow. Save time, avoid hassle and book your parking slot in just a few clicks.', 'general', '2026-09-22 10:32:52', '2026-09-23 12:31:50'),
(32, 'banner_title', 'A Cleaner, Smarter City', 'general', '2026-09-22 10:32:52', '2026-09-23 12:31:50'),
(33, 'banner_desc', 'Let\'s make urban living easier, together.', 'general', '2026-09-22 10:32:52', '2026-09-23 12:31:50'),
(34, 'footer_copyright_text', 'All Rights Reserved.', 'general', '2026-09-22 10:32:52', '2026-09-23 12:31:50'),
(35, 'about_page_content', '{\"branding\":{\"mark\":\"P\",\"name\":\"Smart\",\"highlight\":\"Parking\",\"tagline\":\"Park Smarter. Live Easier.\"},\"seo\":{\"title\":\"About Us - SmartParking\",\"description\":\"Smarter parking for a better tomorrow. Discover the SmartParking story, mission and vision.\"},\"hero\":{\"eyebrow\":\"ABOUT US\",\"title\":\"Smarter Parking\\nfor a Better\",\"highlight\":\"Tomorrow\",\"description\":\"We are on a mission to make parking simple,\\nconvenient and stress-free for everyone.\\nSmartParking connects drivers with secure\\nand reliable parking spaces across the city.\",\"image\":\"images\\/about\\/hero.png\",\"alt\":\"Modern parking garage with yellow pillars\",\"badge_title\":\"Easy Parking\",\"badge_text\":\"Better Living\"},\"story\":{\"eyebrow\":\"OUR STORY\",\"title\":\"How It All\",\"highlight\":\"Started\",\"description\":\"SmartParking was founded with a simple idea — parking should be easy, fast and accessible. We noticed how frustrating it can be to find a safe and reliable parking spot, especially in busy areas. That’s why we built SmartParking — a smart platform that helps you find, book and manage parking spaces in just a few clicks.\",\"image\":\"images\\/about\\/story.png\",\"alt\":\"SmartParking facility entrance\",\"badge_title\":\"Smart Solutions\",\"badge_text\":\"for Modern Cities\"},\"mission\":{\"title\":\"Our\",\"highlight\":\"Mission\",\"description\":\"To simplify the parking experience by providing safe, reliable and accessible parking solutions for everyone.\",\"icon\":\"bullseye\"},\"vision\":{\"title\":\"Our\",\"highlight\":\"Vision\",\"description\":\"To become the leading parking platform in every city, making urban mobility smarter and more convenient.\",\"icon\":\"eye-fill\"},\"difference\":{\"eyebrow\":\"WHY CHOOSE US\",\"title\":\"What Makes Us\",\"highlight\":\"Different\",\"description\":\"We’re not just about parking — we’re about making your life easier.\",\"image\":\"images\\/about\\/difference.png\",\"alt\":\"Driver using the SmartParking app in a parking garage\",\"badge\":\"More than\\njust parking\"},\"features\":[{\"title\":\"Secure & Safe\",\"description\":\"Your vehicle is always in safe hands.\",\"icon\":\"shield-fill-check\"},{\"title\":\"Quick & Easy\",\"description\":\"Find and book in just a few taps.\",\"icon\":\"lightning-fill\"},{\"title\":\"Wide Coverage\",\"description\":\"Multiple locations across the city.\",\"icon\":\"geo-alt-fill\"},{\"title\":\"24\\/7 Support\",\"description\":\"We’re always here to help.\",\"icon\":\"emoji-smile\"}],\"statistics\":[{\"value\":\"10,000+\",\"label\":\"Happy Customers\",\"icon\":\"people-fill\"},{\"value\":\"50+\",\"label\":\"Parking Locations\",\"icon\":\"geo-alt-fill\"},{\"value\":\"25,000+\",\"label\":\"Bookings Completed\",\"icon\":\"car-front-fill\"},{\"value\":\"99%\",\"label\":\"Customer Satisfaction\",\"icon\":\"shield-fill-check\"}],\"navigation\":[{\"label\":\"Home\",\"url\":\"\\/\"},{\"label\":\"Services\",\"url\":\"\\/services\"},{\"label\":\"How It Works\",\"url\":\"\\/how-it-works\"},{\"label\":\"Parking Locations\",\"url\":\"\\/find-parking\"},{\"label\":\"About\",\"url\":\"\\/about\"}],\"footer\":{\"description\":\"SmartParking makes urban living easier with safe, secure and convenient parking solutions.\",\"links_title\":\"Quick Links\",\"support_title\":\"Support\",\"app_title\":\"Download Our App\",\"app_description\":\"Book parking on the go.\",\"google_url\":\"https:\\/\\/play.google.com\\/store\",\"apple_url\":\"https:\\/\\/www.apple.com\\/app-store\\/\",\"google_caption\":\"GET IT ON\",\"google_label\":\"Google Play\",\"apple_caption\":\"Download on the\",\"apple_label\":\"App Store\",\"copyright\":\"© 2024 SmartParking. All rights reserved.\",\"tagline\":\"A Smarter Way to Park\"},\"support\":[{\"label\":\"Help Center\",\"url\":\"\\/how-it-works#faq\"},{\"label\":\"Contact Us\",\"url\":\"mailto:support@smartparking.com\"},{\"label\":\"Terms of Service\",\"url\":\"\\/#footer\"},{\"label\":\"Privacy Policy\",\"url\":\"\\/#footer\"},{\"label\":\"FAQ\",\"url\":\"\\/how-it-works#faq\"}],\"socials\":[{\"label\":\"Facebook\",\"icon\":\"facebook\",\"url\":\"https:\\/\\/facebook.com\"},{\"label\":\"Instagram\",\"icon\":\"instagram\",\"url\":\"https:\\/\\/instagram.com\"},{\"label\":\"Twitter\",\"icon\":\"twitter\",\"url\":\"https:\\/\\/twitter.com\"},{\"label\":\"LinkedIn\",\"icon\":\"linkedin\",\"url\":\"https:\\/\\/linkedin.com\"},{\"label\":\"YouTube\",\"icon\":\"youtube\",\"url\":\"https:\\/\\/youtube.com\"}]}', 'about', '2026-09-23 11:06:10', '2026-09-23 11:06:10'),
(36, 'admin_login_content', '{\"branding\":{\"name\":\"Smart\",\"highlight\":\"Parking\",\"tagline\":\"Smart Parking\",\"tagline_suffix\":\"Live, Easy.\",\"logo\":\"images\\/admin-login\\/logo.svg\"},\"hero\":{\"title\":\"Smarter\\r\\nParking\\r\\nfor a Better\",\"highlight\":\"Tomorrow\",\"description\":\"Manage. Monitor. Simplify.\",\"image\":\"images\\/admin-login\\/background.png\",\"alt\":\"Secure modern parking entrance at night\",\"footer\":\"PARK SAFE\\r\\nDRIVE HAPPY\"},\"feature_1\":{\"icon\":\"car-front-fill\",\"label\":\"Real-time\\r\\nAvailability\"},\"feature_2\":{\"icon\":\"shield-shaded\",\"label\":\"Secure\\r\\n& Safe\"},\"feature_3\":{\"icon\":\"bar-chart-fill\",\"label\":\"Smart\\r\\nManagement\"},\"form\":{\"page_title\":\"Admin Login - SmartParking\",\"new_here\":\"New here?\",\"contact_label\":\"Contact Admin\",\"contact_url\":\"mailto:admin@admin.com\",\"title\":\"Welcome Back\",\"description\":\"Login to access your admin panel\",\"email_label\":\"Email \\/ Username\",\"email_placeholder\":\"Enter your email or username\",\"password_label\":\"Password\",\"password_placeholder\":\"Enter your password\",\"remember_label\":\"Remember me\",\"forgot_label\":\"Forgot password?\",\"submit_label\":\"Login\",\"divider\":\"OR\",\"otp_label\":\"Login with Admin OTP\",\"copyright\":\"© 2026 SmartParking. All rights reserved.\"},\"otp\":{\"title\":\"Admin OTP Login\",\"description\":\"Enter your administrator email to receive a one-time login code.\",\"send_label\":\"Send login code\",\"code_label\":\"One-time code\",\"code_placeholder\":\"Enter the 6-digit code\",\"verify_label\":\"Verify & Login\",\"back_label\":\"Back to password login\",\"help\":\"Codes expire after 10 minutes. After signing in, you can change your password from Profile.\",\"unavailable\":\"Email delivery is not configured yet. Please use your password or contact the administrator.\"}}', 'admin_login', '2026-09-23 11:21:58', '2026-09-23 11:24:46');
